namespace {
// The supplied browser window bridge reads this fixed app domain, including
// when hosted in an app-shim process whose own bundle identifier differs.
const CFStringRef kWindowEffectPreferenceDomain = CFSTR("dev.aux.browser");
const CFStringRef kWindowVibrancyDisabledKey =
    CFSTR("windowBackgroundVibrancyDisabled");

bool ReadWindowVibrancyDisabled() {
  CFPreferencesAppSynchronize(kWindowEffectPreferenceDomain);
  base::apple::ScopedCFTypeRef<CFPropertyListRef> value(
      CFPreferencesCopyAppValue(kWindowVibrancyDisabledKey,
                                kWindowEffectPreferenceDomain));
  return value && CFGetTypeID(value.get()) == CFBooleanGetTypeID() &&
         CFBooleanGetValue(static_cast<CFBooleanRef>(value.get()));
}

std::optional<int> ReadWindowGlassVariant() {
  if (@available(macOS 26, *)) {
    CFPreferencesAppSynchronize(kWindowEffectPreferenceDomain);
    base::apple::ScopedCFTypeRef<CFPropertyListRef> value(
        CFPreferencesCopyAppValue(CFSTR("liquidGlassVariant"),
                                  kWindowEffectPreferenceDomain));
    int variant = 0;
    if (value && CFGetTypeID(value.get()) == CFNumberGetTypeID() &&
        CFNumberGetValue(static_cast<CFNumberRef>(value.get()),
                         kCFNumberIntType, &variant) &&
        variant >= 1 && variant <= 20) {
      return variant;
    }
  }
  return std::nullopt;
}

bool IsGlassBackgroundEffectView(NSView* view) {
  if (@available(macOS 26, *)) {
    Class glass_class = NSClassFromString(@"NSGlassEffectView");
    return glass_class && [view isKindOfClass:glass_class];
  }
  return false;
}

NSView* FindWindowBackgroundEffectView(NSView* root) {
  for (NSView* child in root.subviews) {
    if ([child isKindOfClass:[NSVisualEffectView class]] ||
        IsGlassBackgroundEffectView(child)) {
      return child;
    }
  }
  return nil;
}

NSView* FindCompositorSuperview(NSView* root) {
  if ([root isKindOfClass:[ViewsCompositorSuperview class]]) {
    return root;
  }
  for (NSView* child in root.subviews) {
    if (NSView* compositor = FindCompositorSuperview(child)) {
      return compositor;
    }
  }
  return nil;
}

NSView* CreateBrowserWindowBackgroundEffectView(
    NSRect bounds,
    bool fullscreen,
    bool disabled,
    std::optional<int> glass_variant) {
  NSView* effect = nil;
  if (@available(macOS 26, *)) {
    Class glass_class = NSClassFromString(@"NSGlassEffectView");
    if (!fullscreen && glass_class) {
      effect = [[glass_class alloc] initWithFrame:bounds];
      if (glass_variant) {
        [effect setValue:@(*glass_variant) forKey:@"variant"];
      }
      // Preserve the supplied optional AppKit blending selector; do not select
      // a new material or substitute a custom-painted backdrop.
      SEL selector =
          NSSelectorFromString(@"_setVibrantBlendingStyleForSubtree:");
      if ([effect respondsToSelector:selector]) {
        reinterpret_cast<void (*)(id, SEL, NSInteger)>(objc_msgSend)(
            effect, selector, 0);
      }
    }
  }
  if (!effect) {
    NSVisualEffectView* visual =
        [[NSVisualEffectView alloc] initWithFrame:bounds];
    visual.material = NSVisualEffectMaterialUnderWindowBackground;
    visual.blendingMode = NSVisualEffectBlendingModeBehindWindow;
    visual.state = NSVisualEffectStateFollowsWindowActiveState;
    effect = visual;
  }
  effect.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
  effect.hidden = disabled;
  return effect;
}

void AttachCompositorToWindowBackground(NSView* root,
                                        NSView* effect,
                                        NSView* compositor) {
  NSView* container = root;
  if (IsGlassBackgroundEffectView(effect)) {
    SEL selector = @selector(contentView);
    if ([effect respondsToSelector:selector]) {
      id content = reinterpret_cast<id (*)(id, SEL)>(objc_msgSend)(effect,
                                                                 selector);
      if ([content isKindOfClass:[NSView class]]) {
        container = content;
      }
    }
  }
  [compositor removeFromSuperview];
  compositor.frame = container.bounds;
  compositor.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
  [container addSubview:compositor];
}

}  // namespace

NativeWidgetNSWindowBridge::~NativeWidgetNSWindowBridge() {
  window_effect_preferences_timer_.Stop();
  if (window_effect_preferences_observed_) {
    DCHECK([NSThread isMainThread]);
    CFNotificationCenterRemoveObserver(
        CFNotificationCenterGetDarwinNotifyCenter(), this,
        kWindowEffectPreferenceDomain, nullptr);
  }

void NativeWidgetNSWindowBridge::StartWindowEffectPreferencesObserver() {
  DCHECK([NSThread isMainThread]);
  window_vibrancy_disabled_ = ReadWindowVibrancyDisabled();
  window_glass_variant_ = ReadWindowGlassVariant();
  if (window_effect_preferences_observed_) {
    return;
  }
  CFNotificationCenterAddObserver(
      CFNotificationCenterGetDarwinNotifyCenter(), this,
      [](CFNotificationCenterRef, void* observer, CFStringRef name,
         const void*, CFDictionaryRef) {
        if (name && CFEqual(name, kWindowEffectPreferenceDomain)) {
          static_cast<NativeWidgetNSWindowBridge*>(observer)
              ->UpdateWindowEffectPreferences();
        }
      },
      kWindowEffectPreferenceDomain, nullptr,
      CFNotificationSuspensionBehaviorDeliverImmediately);
  window_effect_preferences_observed_ = true;
  window_effect_preferences_timer_.Start(
      FROM_HERE, base::Milliseconds(250),
      base::BindRepeating(
          &NativeWidgetNSWindowBridge::UpdateWindowEffectPreferences,
          factory_.GetWeakPtr()));
}

void NativeWidgetNSWindowBridge::ReplaceWindowBackgroundEffectView(
    bool fullscreen) {
  NSView* compositor = FindCompositorSuperview(bridged_view_);
  [FindWindowBackgroundEffectView(bridged_view_) removeFromSuperview];
  NSView* effect = CreateBrowserWindowBackgroundEffectView(
      bridged_view_.bounds, fullscreen, window_vibrancy_disabled_,
      window_glass_variant_);
  [bridged_view_ addSubview:effect positioned:NSWindowBelow relativeTo:nil];
  if (compositor) {
    AttachCompositorToWindowBackground(bridged_view_, effect, compositor);
  }
}

void NativeWidgetNSWindowBridge::UpdateWindowEffectPreferences() {
  DCHECK([NSThread isMainThread]);
  const bool disabled = ReadWindowVibrancyDisabled();
  const std::optional<int> variant = ReadWindowGlassVariant();
  const bool disabled_changed = disabled != window_vibrancy_disabled_;
  const bool variant_changed = variant != window_glass_variant_;
  window_vibrancy_disabled_ = disabled;
  window_glass_variant_ = variant;
  NSView* effect = FindWindowBackgroundEffectView(bridged_view_);
  if (!effect) {
    return;
  }
  if (disabled_changed) {
    effect.hidden = disabled;
    if (is_translucent_window_ && !IsWindowModalSheet()) {
      window_.opaque = disabled;
      NSColor* background = NSColor.windowBackgroundColor;
      if (@available(macOS 26, *)) {
        if (!disabled) {
          background = [background colorWithAlphaComponent:0.001];
        }
      }
      window_.backgroundColor = background;
    }
  }
  if (variant_changed && IsGlassBackgroundEffectView(effect)) {
    if (variant) {
      [effect setValue:@(*variant) forKey:@"variant"];
    } else {
      ReplaceWindowBackgroundEffectView(
          (window_.styleMask & NSWindowStyleMaskFullScreen) != 0);
    }
  }
}

